arguments.command:
cd /app && python3 -c "
import subprocess
seqs={}; name=None
for line in open('sequences.fasta'):
    line=line.strip()
    if line.startswith('>'): name=line[1:]; seqs[name]=''
    else: seqs[name]+=line
inp=seqs['input']
p=215
comp={'a':'t','t':'a','g':'c','c':'g'}
def rc(s): return ''.join(comp[c] for c in reversed(s))
def tm(s):
    r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',s],capture_output=True,text=True)
    return float(r.stdout)
# forward anneal downstream
print('FWD:')
fwd={}
for L in range(15,46):
    s=inp[p:p+L]; t=tm(s); fwd[L]=(s,t)
    if 58<=t<=72: print('F',L,round(t,2))
print('REV:')
rev={}
for L in range(15,46):
    s=rc(inp[p-L:p]); t=tm(s); rev[L]=(s,t)
    if 58<=t<=72: print('R',L,round(t,2))
" 2>&1 | head -80

